@once
<style>
.cm-page{max-width:1440px;margin:0 auto;padding:28px 32px;color:#203c30;font-family:Inter,system-ui,sans-serif;font-size:14px;line-height:1.5;min-width:0}.cm-page *{box-sizing:border-box}.cm-header{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;margin-bottom:24px}.cm-page h1{font-size:24px;line-height:1.3;font-weight:700;margin:0 0 6px}.cm-page h2{font-size:16px;font-weight:650;margin:0 0 6px}.cm-muted{color:#6b7b74;font-size:13px}.cm-grid{display:grid;grid-template-columns:minmax(260px,340px) minmax(0,1fr);gap:20px;align-items:start}.cm-card{background:white;border:1px solid #e1e8e4;border-radius:16px;padding:22px;min-width:0}.cm-toolbar{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin:18px 0}.cm-page label{display:block;font-size:13px;font-weight:600;margin-bottom:6px}.cm-page input,.cm-page select,.cm-page textarea{width:100%;min-height:42px;border:1px solid #cfdad3;border-radius:9px;padding:10px 12px;font:inherit;background:white;color:inherit}.cm-field{margin-bottom:16px}.cm-page textarea{resize:vertical;min-height:90px}.cm-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:10px 16px;min-height:42px;border-radius:9px;border:1px solid #cfdad3;background:white;color:#276145;font:600 13px Inter,system-ui,sans-serif;text-decoration:none;cursor:pointer}.cm-primary{background:var(--green-500,#04a052);border-color:var(--green-500,#04a052);color:white}.cm-page :focus-visible{outline:2px solid #078749;outline-offset:3px}.cm-badge{display:inline-block;background:#e9f7ef;color:#087341;padding:4px 10px;border-radius:20px;font-size:11px;font-weight:600}.cm-badge.off{background:#f1f3f2;color:#637069}.cm-entry{padding:18px 0;border-top:1px solid #e7ece9}.cm-entry:first-child{border-top:0}.cm-entry summary{cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:14px;list-style:none}.cm-entry summary::-webkit-details-marker{display:none}.cm-entry[open] summary{margin-bottom:18px}.cm-edit-label{color:#087341;font-size:13px;white-space:nowrap}.cm-entry[open] .cm-edit-label{display:none}.cm-form-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(130px,1fr);gap:14px}.cm-alert{padding:14px 16px;border:1px solid #bde3cb;background:#effaf3;color:#24643d;border-radius:10px;margin-bottom:18px}.cm-error{border-color:#ecc8c8;background:#fff4f4;color:#9b3030}.cm-empty{padding:36px 20px;text-align:center;color:#6b7b74}.cm-pagination{margin-top:20px}.cm-time{font-size:12px;color:#7a8880;white-space:nowrap}.cm-message{white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0}.cm-list-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.cm-help{margin:6px 0 18px;color:#6b7b74;font-size:13px}@media(max-width:900px){.cm-grid{grid-template-columns:1fr}}@media(max-width:600px){.cm-page{padding:20px 16px}.cm-header{flex-direction:column}.cm-page h1{font-size:21px}.cm-card{padding:18px}.cm-form-grid{grid-template-columns:1fr;gap:0}.cm-list-head{align-items:flex-start;flex-direction:column}.cm-toolbar>*{flex:1 1 140px}}
</style>
@endonce
